    'RegisterSimpleRisk'=>'Региструјте SimpleRisk',
    'RegistrationText'=>'Регистрованим СимплеРиск инстанцама се одмах одобрава приступ додацима за надоградњу и оквир безбедних контрола (СЦФ). Упграде Ектра пружа могућност прављења резервне копије и надоградње ваше СимплеРиск инстанце једним кликом на дугме. Сецуре Цонтролс Фрамеворк (СЦФ) Ектра пружа заједнички оквир контроле који је интегрисан у функционалност СимплеРиск Говернанце. Након регистрације СимплеРиск-а, ваше регистрационе информације ће бити послате на сервер који хостује СимплеРиск. СимплеРиск ће користити достављене информације о регистрацији за обавештавање клијената о новим издањима и безбедносним исправкама. Чин регистрације СимплеРиск-а ће вас укључити у наше маркетиншке комуникације, али можете се одустати у било ком тренутку користећи везу за одјаву у овим комуникацијама. СимплеРиск поштује приватност наших купаца и информације које су нам достављене кроз СимплеРиск процес регистрације никада неће бити продате трећој страни.',
