    // Configure Hub - tile descriptions (system category)
    'SettingsDesc'                        => 'Конфигуришите подешавања за цео систем: основни URL, безбедност, подразумевани језик, временску зону, подразумеване вредности за бодовање ризика и још много тога.',
    'SettingsPreferencesDesc'             => 'Подразумеване вредности и преференције понашања у SimpleRisk-у: језик, временска зона, статуси ревизије, захтеви за мапирање ризика, прекидачи понашања корисничког интерфејса и слично.',
    'SettingsFileUploadDesc'              => 'Дозвољени типови отпремања датотека и ограничења величине за различита поља прилога датотека.',
    'SettingsMailDesc'                    => 'SMTP конфигурација за обавештења о одлазној е-пошти, укључујући транспорт, хост, аутентификацију и адресу за одговор.',
    'SettingsBackupsDesc'                 => 'Конфигуришите чување резервних копија, заказивање и линкове за преузимање за резервне копије базе података SimpleRisk.',
    'SettingsSecurityDesc'                => 'Подешавања безбедности за аутентификацију, сесију, политику лозинки, основни URL и API.',
    'SettingsLoggingDesc'                 => 'Конфигурација евидентирања грешака и ревизије: нивои евидентирања, задржавање и локација датотека евидентирања.',
    'HealthCheckDesc'                     => 'Дијагностикујте статус система: PHP верзију, екстензије, дозволе за датотеке, повезивање са базом података, cron распоред и додатне активације.',
    'AnnouncementsDesc'                   => 'Саставите и управљајте банер обавештењима видљивим свим корисницима.',
    'RegisterAndUpgradeDesc'              => 'Региструјте своју SimpleRisk инсталацију, унесите или обновите кључ претплате и покрените надоградње Core/Extra једним кликом.',
    'QueueMonitorDesc'                    => 'Прегледајте редослед позадинских послова: задатке на чекању, задатке у току и неуспешне задатке.',
    'ExtrasDesc'                          => 'Активирајте, деактивирајте и конфигуришите SimpleRisk Extras (плаћене додатке).',
    'ArtificialIntelligenceExtraDesc'     => 'Додатна вештачка интелигенција пружа побољшану анализу ризика (укључујући FAIR процене) и прилагођену документацију.',
    'CustomizationExtraDesc'              => 'Додатна функција за прилагођавање омогућава додавање и уклањање различитих типова поља и динамичко креирање прилагођених шаблона страница.',
    'NotificationExtraDesc'               => 'Додатна функција за обавештења путем е-поште омогућава SimpleRisk-у да шаље обавештења путем е-поште када се ризици поднесу, измене или се на њих на други начин предузму мере. Ова додатна функција се такође може додати као заказана скрипта за слање рутинских подсетника када су ризици спремни за преглед од стране менаџмента. У производу SimpleRisk Core, без ове додатне функције, никаква обавештења се не комуницирају изван самог алата.',
    'VulnerabilityManagementExtraDesc'    => 'Додатна опција за управљање рањивостима пружа корисницима могућност интеграције своје инстанце SimpleRisk-а са Qualys, Tenable.io или Rapid7 Nexpose/InsightVM и увоза података о средствима и рањивостима у SimpleRisk. Одатле можете одабрати које локације желите да покријете, одредити које оцене рањивости треба увести и проценити које рањивости се претварају у ризике како бисте их пратили.',
    'IncidentManagementExtraDesc'         => 'Додатак за управљање инцидентима заснован је на NIST 800-61 Водичу за руковање инцидентима у области безбедности рачунара и пружа могућности управљања инцидентима из самог система SimpleRisk.',

    // Configure Hub - tile descriptions (customization category)
    'RedefineNamingConventionsDesc'       => 'Преименујте терминологију SimpleRisk-а (Ризик, Средство, Оквир итд.) у корисничком интерфејсу.',
    'RiskConfigurationDesc'               => 'Конфигуришите правила бодовања ризика: нивое, апетит, прагове SLA и класичне / доприносеће формуле ризика.',
    'RiskAndThreatCatalogDesc'            => 'Одржавајте каталог вредности ризика и претњи које се користе у падајућим менијима.',
    'AddAndRemoveValuesDesc'              => 'Управљајте вредностима падајућег менија за поља ризика: локација, извор, категорија, тим, технологија и још много тога.',
    'AssetValuationDesc'                  => 'Конфигуришите скалу за процену имовине и надјачања за процену по имовини.',

    // Configure Hub - tile descriptions (users category)
    'UserManagementDesc'                  => 'Додајте, уредите, онемогућите и ресетујте кориснике; управљајте политиком лозинки.',
    'RoleManagementDesc'                  => 'Дефинишите улоге и дозволе које свака улога додељује.',
    'TeamManagementDesc'                  => 'Креирајте и управљајте тимовима који се користе за филтрирање видљивости записа.',
    'SeparationExtraDesc'                 => 'Додатак за раздвајање на основу тима ограничава преглед ризика само на кориснике који су чланови тима коме је ризик додељен. У производу SimpleRisk Core, без овог додатка, сваки корисник може да види сваки ризик.',
    'CustomAuthenticationExtraDesc'       => 'Додатак за прилагођену аутентификацију пружа подршку за Active Directory и SAML аутентификацију. У производу SimpleRisk Core, без овог додатка, једина опција је креирање нових корисника у SimpleRisk репозиторијуму идентитета.',
    'EncryptionExtraDesc'                 => 'Додатна шифрована база података генерише насумични AES-256-битни кључ за шифровање, а затим га користи за шифровање осетљивог текста пре него што се убаци у базу података SimpleRisk. Ово спречава било кога да види или измени податке без директног коришћења апликације SimpleRisk.',
    'OrganizationManagementDesc'          => "Додатак Организациона хијерархија омогућава дефинисање више пословних јединица које могу да укључују било који број тимова. Корисници затим могу бити распоређени у један или више тимова у оквиру различитих пословних јединица. Ово утиче на могућност корисника да види и користи тимове, кориснике и средства са којима није повезан.",

    // Configure Hub - tile descriptions (data category)
    'DeleteRisksDesc'                     => 'Ризици групног брисања. Користите штедљиво — брисања су трајна.',
    'AuditTrailDesc'                      => 'Претражите и извезите дневник системске ревизије корисничких акција.',
    'ImportExportExtraDesc'               => 'Додатак за увоз-извоз пружа могућност увоза података у SimpleRisk мапирањем поља у CSV датотеци са пољима у бази података SimpleRisk. Може се користити за увоз резултата ревизије из табеле треће стране, резултата скенирања рањивости из другог алата, средстава из ваше CMDB базе података и још много тога. Додатак такође пружа могућност извоза CSV датотека из SimpleRisk-а које садрже ризике, ублажавања, прегледе или комбиновани извештај за сва три фактора.',
    'JiraExtraDesc'                       => 'Jira Integration Extra пружа корисницима могућност двосмерне интеграције са Jira инстанцом. Омогућава повезивање ризика са Jira проблемима, као и синхронизацију њихових података, статуса и коментара.',
    'APIExtraDesc'                        => 'API Extra омогућава корисницима да користе RESTful API за креирање скриптованих интеракција са другим апликацијама како би постигли напредну аутоматизацију и искористили постојећу инфраструктуру.',
    'AdvancedSearchExtraDesc'             => "Напредна претрага додатно проширује функционалност поља за претрагу у горњој траци како би се могли пронаћи ризици текстуалном претрагом података о ризику.",
    'AssessmentsExtraDesc'                => 'Додатна процена ризика пружа корисницима могућност дефинисања контаката, креирања питања (укључујући логику), састављања више питања помоћу шаблона упитника, креирања упитника и њиховог слања контактима, прегледа резултата упитника, додавања ризика на основу тих резултата и упоређивања резултата током времена, увоза и извоза екстерно прилагођених процена и прегледа ревизорског трага процене ризика.',
    'ActiveAssessmentsDesc'               => 'Прегледајте и управљајте проценама које су тренутно у току.',
    'WorkflowsExtraDesc'                  => 'Workflows Extra пружа визуелни, догађајима вођен механизам за управљање токовима рада који аутоматизује акције управљања ризицима као одговор на догађаје унутар SimpleRisk-а. Можете дизајнирати токове рада који се покрећу при променама — као што је слање, ажурирање или преглед ризика — како бисте усмерили одобрења, доделили посао и одржали свој процес у току без ручне интервенције.',

    // Configure Hub - tile descriptions (frameworks category)
    'UCFExtraDesc'                        => 'Унифицирани оквир за усаглашеност (UCF) Extra је интеграција на нивоу API-ја између Унифицираног оквира за усаглашеност и SimpleRisk-а. Његово омогућавање вам омогућава да увезете одабране оквире и контролишете мапирања директно из UCF-а.',
    'SCFExtraDesc'                        => "Оквир безбедних контрола (SCF) Екстра је директна интеграција између Оквира безбедних контрола и SimpleRisk-а. Он увози SCF-ов каталог контрола и њихова мапирања у широком спектру оквира за усклађеност и сајбер безбедност у SimpleRisk-ову функционалност управљања, тако да можете усвојити оквире који су вам потребни и управљати њиховим контролама без ручног креирања.",

    // Configure Hub - tile descriptions (maintenance category)
    'FixReviewDatesDesc'                  => 'Мигрирај застареле VARCHAR колоне са датумом прегледа на одговарајуће типове датума. Видљиво само када је потребно.',
    'FixFileEncodingIssuesDesc'           => 'Поправи отпремљене датотеке са проблемима са кодирањем знакова. Видљиво само када је потребно.',
    'DatabaseUpgradeDesc'                 => 'Ручно покрените рутину надоградње базе података SimpleRisk.',

