    'EncryptionRestoreCtaHelp'              => 'Изаберите ово ако је валидација пронашла проблеме и потребно је да се вратите на стање пре шифровања.',
    'EncryptionRestoreTitle'                => 'Врати из резервне копије?',
    'EncryptionRestoreBodyWhy'              => 'Враћање на снимак пре шифровања снимљен на почетку најновије активације. Изаберите ову опцију ако је валидација након активације пронашла проблеме и потребно је да одустанете од шифровања.',
    'EncryptionRestoreBodyWhat'             => 'Сваки ред записан у базу података након креирања резервне копије биће трајно изгубљен — укључујући ризике, мере за ублажавање ризика, уносе у дневник ревизије и све друге промене направљене од активације. Додатна шифрована база података биће деактивирана као део враћања.',
    'EncryptionDeleteBackupCta'             => 'Обришите резервну копију пре шифровања',
    'EncryptionDeleteBackupCtaHelp'         => 'Изаберите ово када се заврши валидација након шифровања. Уклањање нешифрованог снимка је оно што шифровање чини заправо заштитним.',
    'EncryptionDeleteBackupTitle'           => 'Желите ли да обришете резервну копију пре шифровања?',
    'EncryptionDeleteBackupBodyWhy'         => 'Уклањање нешифрованог снимка ваших података који је снимљен на почетку последње активације. Чување на неодређено време поништава сврху шифровања — свако ко има приступ бази података може да прочита копију пре шифровања.',
    'EncryptionDeleteBackupBodyWhat'        => 'Резервна копија у бази података се одмах брише. Више нећете моћи да користите опцију „Врати из резервне копије“ да бисте вратили базу података у стање пре шифровања. Ако касније пронађете проблеме са шифровањем, једини пут опоравка биће ново враћање базе података из оперативних резервних копија.',
    'EncryptionDeleteBackupError'           => 'Брисање резервне копије није успело. Проверите дневник отклањања грешака и покушајте поново.',
